reg [2:0] seen=0;
wire hit=letter[0] && seen==0;

reg [31:0] reference_count=0;
always @(posedge clk) begin
  if(letter[0] && seen<1) seen<=seen+1;

  reference_count<=(hit) && letter[1];
end

